#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int halveArray(vector<int>& nums){priority_queue<double> pq;double sum=0;for(int x:nums){pq.push(x);sum+=x;}
  double removed=0;int ops=0;while(removed*2<sum){double v=pq.top()/2;pq.pop();removed+=v;pq.push(v);++ops;}return ops;
 }
};
